export type CirclesCopyKey = keyof typeof CIRCLES_COPY;

export function circlesSignupError(locale: Locale, error: string): string {
  return circlesCopy(locale)(Object.prototype.hasOwnProperty.call(CIRCLES_COPY, error) ? error as CirclesCopyKey : "The signup request could not be processed.");
}
export function circlesCopy(locale: Locale = "en") {
  return (key: CirclesCopyKey, values: Record<string, string | number> = {}): string => {
    const index = locale === "tl" ? 0 : locale === "id" ? 1 : locale === "vi" ? 2 : -1;
    const template = index === -1 ? key : CIRCLES_COPY[key][index];
    return template.replace(/\{(\w+)\}/g, (token, name: string) => Object.prototype.hasOwnProperty.call(values, name) ? String(values[name]) : token);
  };
}

const CATEGORY_KEYS: Record<CircleCategory, CirclesCopyKey> = {
  disaster: "Disaster relief", medical: "Medical", education: "Education", community: "Community", family: "Family",
  creator: "Creator support", animals: "Animal care", care: "Care & meals", volunteer: "Volunteer action",
};
export function circlesCategory(locale: Locale, category: CircleCategory): string {
  return circlesCopy(locale)(CATEGORY_KEYS[category]);
}
